INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (91, '巴赫', 'J. S. Bach', '1685—1750', '巴洛克', '德国', '作曲家', ARRAY['音乐家', '德国', '巴洛克'], '巴洛克音乐巨匠，作曲与管风琴大师。他的复调艺术将宗教音乐推向空前的高峰，被誉为音乐之父。', '教堂管风琴师友', '', 'assets/figures/bach.jpg', ARRAY['03-21', '04-01'], ARRAY['诞辰 · 1685年3月21日', '《马太受难曲》首演 · 1727年'], ARRAY['birth', 'event'], '他礼拜弹琴，你替他翻了二十年谱，翻错一页他都不恼。', ARRAY['教堂管风琴师友', '乐谱抄写'], ARRAY['他礼拜弹琴，你替他翻了二十年谱，翻错一页他都不恼。', '那些康塔塔的抄本，落款是你的名，他笑说你是他的笔。']),
  (92, '肖邦', 'Frédéric Chopin', '1810—1849', '19世纪', '波兰', '作曲家', ARRAY['音乐家', '波兰', '钢琴'], '波兰作曲家与钢琴家，钢琴诗歌的化身。他的夜曲与叙事曲深挚优雅，把民族的忧伤化作旋律。', '巴黎沙龙主', '', 'assets/figures/chopin.jpg', ARRAY['03-01', '10-01'], ARRAY['诞辰 · 1810年3月1日', '巴黎首演 · 1832年'], ARRAY['birth', 'event'], '他在巴黎的沙龙，你是常驻东道，客人你引，酒你斟。', ARRAY['巴黎沙龙主', '钢琴调律'], ARRAY['他在巴黎的沙龙，你是常驻东道，客人你引，酒你斟。', '他的钢琴，音准只有你调得动，演出前夜你都在。']),
  (93, '柴可夫斯基', 'Pyotr Tchaikovsky', '1840—1893', '19世纪', '俄国', '作曲家', ARRAY['音乐家', '俄国', '浪漫'], '俄国作曲家，以旋律著称。芭蕾《天鹅湖》《胡桃夹子》与多部交响曲至今长演不衰。', '芭蕾乐队替', '', 'assets/figures/tchaikovsky.jpg', ARRAY['05-07', '08-01'], ARRAY['诞辰 · 1840年5月7日', '《1812序曲》完成 · 1880年'], ARRAY['birth', 'event'], '他的芭蕾首演，乐队里你坐第一排，错拍你先示意。', ARRAY['芭蕾乐队替', '铁路随行'], ARRAY['他的芭蕾首演，乐队里你坐第一排，错拍你先示意。', '他坐火车采风，包厢常备你一杯茶，沿途站名你替他记。']),
  (94, '汉尼拔', 'Hannibal Barca', '前247—前183', '古希腊', '迦太基', '统帅', ARRAY['军事', '迦太基', '古代'], '迦太基统帅，第二次布匿战争的灵魂。他翻越阿尔卑斯山奇袭罗马，是古代最杰出的军事天才之一。', '象队驯手', '', 'assets/figures/hannibal.jpg', ARRAY['08-01', '10-01'], ARRAY['诞辰 · 前247年8月1日', '翻越阿尔卑斯 · 前218年'], ARRAY['birth', 'event'], '翻阿尔卑斯那群象，你喂了最久，它们只认你的哨声。', ARRAY['象队驯手', '翻山向导'], ARRAY['翻阿尔卑斯那群象，你喂了最久，它们只认你的哨声。', '他问路问到你，你指了最难的那条，因为他赌得起。']),
  (95, '理查一世', 'Richard the Lionheart', '1157—1199', '中世纪', '英格兰', '国王', ARRAY['军事', '英格兰', '十字军'], '英格兰国王，第三次十字军东征的核心人物。他以勇武善战闻名，却多在海外征战，在英格兰本土反倒少见。', '十字军随医', '', 'assets/figures/richard1.jpg', ARRAY['09-08', '03-09'], ARRAY['诞辰 · 1157年9月8日', '加冕 · 1189年3月9日'], ARRAY['birth', 'throne'], '东征的伤兵，归你照料，绷带你一匹匹拆洗。', ARRAY['十字军随医', '城堡守卫'], ARRAY['东征的伤兵，归你照料，绷带你一匹匹拆洗。', '他出海征战，城堡的墙你替他把过，缺口你先补。']),
  (96, '威灵顿公爵', 'Duke of Wellington', '1769—1852', '18—19世纪', '英国', '元帅', ARRAY['军事', '英国', '拿破仑战争'], '英国陆军元帅，在滑铁卢击败拿破仑的统帅。他后来出任首相，以稳健保守的政治风格著称。', '滑铁卢副官', '', 'assets/figures/wellington.jpg', ARRAY['05-01', '06-18'], ARRAY['诞辰 · 1769年5月1日', '滑铁卢之战 · 1815年6月18日'], ARRAY['birth', 'event'], '滑铁卢那天，传令的快马你骑了一匹，马汗你替他擦。', ARRAY['滑铁卢副官', '乡居邻居'], ARRAY['滑铁卢那天，传令的快马你骑了一匹，马汗你替他擦。', '他退隐后，庄园和你家只隔一道篱，猎狐常碰头。']),
  (97, '耶稣', 'Jesus of Nazareth', '约前4—约30', '公元1世纪', '巴勒斯坦', '传教士', ARRAY['宗教', '巴勒斯坦', '基督教'], '公元一世纪的犹太传教士，基督教的中心人物。他以寓言与门徒传教，其教导与影响深远地塑造了世界文明。', '加利利船夫', '', 'assets/figures/jesus.jpg', ARRAY['12-25', '01-01'], ARRAY['诞辰（传统） · 约元年12月25日', '开始传道 · 约29年'], ARRAY['birth', 'event'], '他讲道，你划船渡他过加利利海，桨是你摇的。', ARRAY['加利利船夫', '筵席分食'], ARRAY['他讲道，你划船渡他过加利利海，桨是你摇的。', '五饼二鱼那回，分食的篮子是你提的，空了你又背回去。']),
  (98, '奥古斯丁', 'Augustine of Hippo', '354—430', '4—5世纪', '北非', '神学家', ARRAY['宗教', '北非', '神学'], '北非出身的神学家与哲学家，希波主教。《忏悔录》与《上帝之城》奠定了基督教思想的重要框架。', '希波抄录', '', 'assets/figures/augustine.jpg', ARRAY['11-13', '04-01'], ARRAY['诞辰 · 354年11月13日', '受洗 · 387年4月'], ARRAY['birth', 'event'], '《忏悔录》的稿，你替他一句句录，错处他用指尖点。', ARRAY['希波抄录', '花园园丁'], ARRAY['《忏悔录》的稿，你替他一句句录，错处他用指尖点。', '他庭院里的那棵树，你浇了多年，他常在树下想事。']),
  (99, '托马斯·阿奎那', 'Thomas Aquinas', '约1225—1274', '13世纪', '意大利', '神学家', ARRAY['宗教', '意大利', '经院哲学'], '中世纪神学家与哲学家，经院哲学的集大成者。他以理性调和信仰，著成《神学大全》，影响西方思想数百年。', '巴黎学堂助教', '', 'assets/figures/aquinas.jpg', ARRAY['01-28', '12-01'], ARRAY['诞辰 · 约1225年1月28日', '入多明我会 · 1244年'], ARRAY['birth', 'event'], '他讲经院哲学，板书你替他写，他口若悬河你手不停。', ARRAY['巴黎学堂助教', '修道院厨下'], ARRAY['他讲经院哲学，板书你替他写，他口若悬河你手不停。', '修道院的厨房，你管着他爱吃的鱼，节期都是你张罗。']),
  (100, '马丁·路德', 'Martin Luther', '1483—1546', '15—16世纪', '德意志', '神学家', ARRAY['宗教', '德国', '改革'], '德意志神学家，宗教改革发起人。1517年《九十五条论纲》冲击了天主教会的权威，开启新教传统。', '威登堡门房', '', 'assets/figures/luther.jpg', ARRAY['11-10', '10-31'], ARRAY['诞辰 · 1483年11月10日', '《九十五条论纲》 · 1517年10月31日'], ARRAY['birth', 'event'], '1517年那扇门，钥匙在你腰间，钉锤是你递的。', ARRAY['威登堡门房', '赎罪券对账'], ARRAY['1517年那扇门，钥匙在你腰间，钉锤是你递的。', '他贴论纲前，赎罪券的账你替他算清，谁多收的一目了然。'])
